// The registered plugin data of each schema library generated by
// scripts/usdGenSchema.mjs equals the files kept in its plugin/ directory:
// upstream's verbatim plugInfo.json and the generatedSchema.usda the script
// verified byte-identical to OpenUSD v26.11.1's.
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'

const LIBRARIES = ['usd', 'usdGeom', 'usdHydra', 'usdLod', 'usdLux', 'usdMedia', 'usdMtlx', 'usdPhysics', 'usdProc', 'usdRender', 'usdRi', 'usdSemantics', 'usdShade', 'usdSkel', 'usdUI', 'usdVol']

for (const lib of LIBRARIES) {
  describe(`${lib} plugin data`, () => {
    const plugin = (name: string) =>
      readFileSync(new URL(`../../usd/${lib}/plugin/${name}`, import.meta.url), 'utf8')
    const load = () => import(`../../usd/${lib}/src/plugin/plugData.ts`) as
      Promise<{ plugInfo: unknown, generatedSchemaUsda: string }>
    it('registers plugin/generatedSchema.usda byte for byte', async () => {
      expect((await load()).generatedSchemaUsda).toBe(plugin('generatedSchema.usda'))
    })
    it('registers plugin/plugInfo.json (plug/info.cpp strips # comment lines)', async () => {
      const json = plugin('plugInfo.json').split('\n').filter(l => !l.trimStart().startsWith('#')).join('\n')
      expect((await load()).plugInfo).toEqual(JSON.parse(json))
    })
  })
}
